// The GOST paint palette (skeudoindustrial surfaces, phase 4): the theme
// package demo/themes/gost_paints, generated by
// tools/industrial_surfaces/gost_palette.py, compiles alone without a
// finding, installs, and a package importing it reads its colours by card
// number and evidence class (var(--gost-a-397), the machine tools'
// blue-green; var(--gost-b-491), the tropical panels' grey-blue).

#include "../../src/core/theme_language/package/theme_manifest.hpp"
#include "gui_forms/anatomy/types/anatomy_types.hpp"
#include "gui_forms/control/control/control.hpp"
#include "gui_forms/control/stable_id/stable_id.hpp"
#include "gui_forms/resources/image_registry/image_registry.hpp"
#include "gui_forms/theme/theme/theme.hpp"
#include "gui_forms/theme/theme_compiler/theme_compiler.hpp"
#include "gui_forms/theme/types/theme_types.hpp"
#include "gui_forms/types/paint_types/paint_types.hpp"

#include <array>
#include <fstream>
#include <iostream>
#include <iterator>
#include <memory>
#include <optional>
#include <string>
#include <string_view>
#include <utility>

namespace {

using namespace gui_forms;

int failures = 0;

void require(bool condition, std::string_view message) {
    if (condition) return;
    std::cerr << "FAIL: " << message << '\n';
    ++failures;
}

std::optional<std::string> read_file(const std::string& path) {
    std::ifstream file(path, std::ios::binary);
    if (!file) return std::nullopt;
    std::string text((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
    return text;
}

constexpr std::array<PartDeclaration, 1> pad_parts{{
    {.name = "face", .role = PartRole::face, .composed_from = {}, .states = {}},
}};
const std::array<ControlAnatomy, 1> controls{{
    {.control_id = "button", .parts = pad_parts, .states = {}, .custom_states = {}, .item_systems = {}},
}};

ThemeCompileOptions options() {
    ThemeCompileOptions made{};
    made.controls = controls;
    made.base = ThemeBase::windows_professional;
    return made;
}

std::string hex_of(std::string_view bytes) {
    return theme_language::package_sha256_hex(theme_language::package_sha256(bytes));
}

// The package as the build embeds it: the manifest and the sheet it names.
std::optional<ThemePackage> palette_package() {
    const std::string directory = GUI_FORMS_GOST_PALETTE_DIR;
    const std::optional<std::string> manifest = read_file(directory + "/theme.json");
    const std::optional<std::string> sheet = read_file(directory + "/gost-paints.theme.css");
    if (!manifest || !sheet) return std::nullopt;
    ThemePackage package{};
    package.manifest = *manifest;
    package.files.push_back(ThemePackageFile{"gost-paints.theme.css", *sheet});
    return package;
}

// A package importing the palette, its sheet `sheet`.
ThemePackage importer(const ThemePackage& palette, std::string_view sheet) {
    ThemePackage made{};
    made.manifest = "{\"format\": \"gui-forms-theme/1\", \"name\": \"probe\", \"version\": \"1.0.0\", \"engine\": "
                    "\">=0.3\", \"sheet\": {\"path\": \"theme.theme.css\", \"sha256\": \"" +
                    hex_of(sheet) + "\"}, \"imports\": {\"gost-paints\": \"" + hex_of(palette.manifest) + "\"}}";
    made.files.push_back(ThemePackageFile{"theme.theme.css", std::string(sheet)});
    return made;
}

class Pad final : public Control {
public:
    explicit Pad(StableId stable_id) : Control(std::move(stable_id)) {}
};

Color text_of(const Theme& theme, const Control& control) {
    const ResolvedControlRecipe recipe = theme.resolve(control, ControlVisualRole::button, ControlVisualContext{});
    return recipe.recipe().text;
}

void test_palette() {
    const std::optional<ThemePackage> palette = palette_package();
    require(palette.has_value(), "the palette package is read");
    if (!palette) return;
    ImageRegistry images{};
    const ThemeLibrary empty{};
    const ThemeCompileResult alone = compile_theme_package(*palette, empty, images, options());
    for (const ThemeCompileDiagnostic& diagnostic : alone.diagnostics()) {
        std::cerr << "  finding: " << diagnostic.code << " " << diagnostic.name << " line " << diagnostic.line << '\n';
    }
    require(alone.succeeded() && alone.diagnostics().empty(), "the palette compiles alone without a finding");

    ThemeLibrary library{};
    require(library.install(*palette).empty() && library.contains("gost-paints"), "the palette installs");
    const std::shared_ptr<Pad> pad = make_control<Pad>(StableId("pad"));
    const ThemeCompileResult teal = compile_theme_package(
        importer(*palette, "@import \"gost-paints\";\n#pad { color: var(--gost-a-397) }\n"), library, images,
        options());
    require(teal.succeeded(), "an importing package reads a class a colour");
    if (teal.succeeded()) {
        require(text_of(*teal.theme(), *pad) == Color::rgba(0x4d, 0x67, 0x6d), "--gost-a-397 is #4d676d");
    }
    const ThemeCompileResult grey_blue = compile_theme_package(
        importer(*palette, "@import \"gost-paints\";\n#pad { color: var(--gost-b-491) }\n"), library, images,
        options());
    require(grey_blue.succeeded(), "and a class b colour");
    if (grey_blue.succeeded()) {
        require(text_of(*grey_blue.theme(), *pad) == Color::rgba(0x43, 0x71, 0x80), "--gost-b-491 is #437180");
    }
    const ThemeCompileResult unknown = compile_theme_package(
        importer(*palette, "@import \"gost-paints\";\n#pad { color: var(--gost-c-520) }\n"), library, images,
        options());
    require(!unknown.succeeded(), "a class c card has no value to read");
}

} // namespace

int main() {
    test_palette();
    if (failures != 0) {
        std::cerr << failures << " failure(s)\n";
        return 1;
    }
    std::cout << "theme GOST palette tests passed\n";
    return 0;
}
